    return in_shape;
}

ge::graphStatus GeluTiling::CheckShape()
{
    OP_LOGD(tilingContext->GetNodeName(), "GeluTiling CheckShape enter.");
    auto inputStorageShape = tilingContext->GetInputShape(0);
